p=argparse.ArgumentParser();p.add_argument('--source',required=True);a=p.parse_args();src=Path(a.source).resolve();repo=Path(__file__).resolve().parent.parent;out=repo/'experimentos/btc-eth-sentimento';out.mkdir(parents=True,exist_ok=True)
read=lambda f:json.loads((src/f).read_text());h=read('web/data/multiasset-history.json');f=read('web/data/multiasset-forward.json');s=read('web/data/local-sentiment.json');context=read('web/data/btc-market-context.json');study=read('web/data/btc-context-study.json')
