data={'snapshotAt':datetime.now(timezone.utc).isoformat(),'mode':'paper_only_static_snapshot','historical':h,'forward':f,'sentiment':s,'btcContext':context,'btcContextStudy':{**study,'results':[summarized(r) for r in study['results']]},'testsPassed':225,'codeManifestSHA256':hashlib.sha256((repo/'app/source-manifest.json').read_bytes()).hexdigest()};(out/'snapshot.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');e=html.escape
rows=''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in [r['label'],r['cost'],f"R$ {r['pnlBRL']:.2f}",r['count'],f"{r['maxDD']*100:.2f}%",r['modelAllowed']])+'</tr>' for r in h['results'])
